using System;using System.Linq;using System.IO;using System.Drawing;using System.Collections.Generic;using System.Windows.Forms;using MakroSoundSwitch;
class PolishVerify {
 static void Assert(bool b,string text){if(!b)throw new Exception(text);Console.WriteLine("PASS: "+text);}
 static IEnumerable<Control> Descendants(Control c){foreach(Control child in c.Controls){yield return child;foreach(var nested in Descendants(child))yield return nested;}}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
 Assert(Features.Name(FeatureType.PlayPauseMedia)=="Play/Pause","Playback label is Play/Pause");Assert(Features.Name(FeatureType.MuteMedia)=="Mute/Unmute","Mute label is Mute/Unmute");
 bool original=Audio.IsMuted();try{Audio.ToggleMuted();Assert(Audio.IsMuted()!=original,"Mute toggle reverses current output mute state");Audio.ToggleMuted();Assert(Audio.IsMuted()==original,"Second mute toggle restores original state");}finally{Audio.SetMuted(original);}
 foreach(var action in new[]{CloseAction.Exit,CloseAction.MinimizeToTaskbar,CloseAction.RunInBackground})using(var dialog=new AppSettingsDialog(new Settings{CloseBehavior=action})){dialog.Show();Application.DoEvents();var all=Descendants(dialog).ToList();var radio=all.OfType<RadioButton>().ToList();Assert(radio.Count==3&&radio.Single(r=>r.Checked).Tag.Equals(action),"Radio setting loads "+action);all.OfType<CheckBox>().Single(c=>c.Text.StartsWith("Run when Windows")).Enabled=false;var next=(CloseAction)(((int)action+1)%3);radio.Single(r=>r.Tag.Equals(next)).Checked=true;all.OfType<Button>().Single(b=>b.Text=="Save settings").PerformClick();Assert(dialog.DialogResult==DialogResult.OK&&dialog.CloseBehavior==next,"Radio setting saves "+next);}
 using(var dialog=new AppSettingsDialog(new Settings())){dialog.Show();Application.DoEvents();using(var b=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(b,new Rectangle(Point.Empty,dialog.Size));b.Save("settings-radio.png");}dialog.Close();}
 using(var form=new Form{ClientSize=new Size(640,360),BackColor=Theme.Bg}){var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(12)};form.Controls.Add(panel);foreach(var type in new[]{FeatureType.Input,FeatureType.NextMedia,FeatureType.PlayPauseMedia,FeatureType.MuteMedia})panel.Controls.Add(new FeatureRow(new ScenarioFeature{Type=type,DeviceId="device"},new List<Device>{new Device{Id="device",Name="Example speakers"}},new List<Device>{new Device{Id="device",Name="Example microphone"}}){Width=600});form.Show();Application.DoEvents();using(var b=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(b,new Rectangle(Point.Empty,form.Size));b.Save("feature-borders.png");}form.Close();}
 }
}
